# Also decode the tcp state codes from /proc/net/tcp
# State 08 = CLOSE_WAIT, 01 = ESTABLISHED, 05 = FIN_WAIT2, 0A = LISTEN
# Let's also inspect tx_queue/rx_queue values for the connections
node -e "
const states = {
  '01': 'ESTABLISHED', '02': 'SYN_SENT', '03': 'SYN_RECV',
  '04': 'FIN_WAIT1',   '05': 'FIN_WAIT2','06': 'TIME_WAIT',
  '07': 'CLOSE',       '08': 'CLOSE_WAIT','09': 'LAST_ACK',
  '0A': 'LISTEN',      '0B': 'CLOSING'
};
const fs = require('fs');
const lines = fs.readFileSync('/proc/net/tcp','utf8').split('\n').slice(1).filter(Boolean);
lines.filter(l => l.includes('0BBB')).forEach(line => {
  const parts = line.trim().split(/\s+/);
  const local = parts[1], remote = parts[2], state = parts[3];
  const txrx = parts[4];
  const [tx, rx] = txrx.split(':').map(h => parseInt(h, 16));
  function decodeAddr(addr) {
    const [ipHex, portHex] = addr.split(':');
    const ip = ipHex.match(/../g).reverse().map(b => parseInt(b,16)).join('.');
    return ip + ':' + parseInt(portHex,16);
  }
  console.log(decodeAddr(local), '->', decodeAddr(remote),
    '| STATE:', states[state] || state,
    '| tx_queue:', tx, 'rx_queue:', rx);
});
" 2>&1

